from pathlib import Path

from docx import Document
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.shared import Inches, Pt

from generate_implemented_project_report import add_figure, heading


ROOT = Path(__file__).resolve().parent
OUTPUT = ROOT / "Digital_Defense_Hub_Final_Theory_Diagram_Report_No_Repeated_Tables.docx"
DIAGRAMS = ROOT / "report_diagrams"


def add_text(document, value):
    paragraph = document.add_paragraph(value)
    paragraph.paragraph_format.space_after = Pt(8)


def page(document, code, title, focus, components, controls, output, formula="No separate mathematical formula is implemented for this subtopic. The project uses the stated workflow, validation rules and recorded evidence rather than an invented numeric formula.", diagram=None, caption=None):
    document.add_page_break()
    heading_item = document.add_heading(f"{code} {title}", level=1)
    heading_item.alignment = WD_ALIGN_PARAGRAPH.CENTER

    add_text(document, f"Digital Defense Hub applies this subtopic to the implemented platform, not as a theoretical feature list. {focus} The source repository combines a React/Vite/TypeScript operator console, a Go REST backend, PostgreSQL persistence, a Python FastAPI AI engine, and Windows-oriented monitoring/sentinel logic. These components are connected through authenticated APIs, tenant context, evidence records and asynchronous workflow handling when a task cannot be completed inside a normal web request.")
    add_text(document, f"Within this subtopic, the important project components are {components}. The backend follows a route, middleware, handler, service and repository path. Middleware establishes authentication, tenant context and permissions before sensitive actions reach the service layer. Repository operations persist organization-scoped records in PostgreSQL. Where the workflow needs analysis, scoring or long-running work, the Go layer coordinates with the Python service or a worker-oriented processing path rather than exposing raw internal operations directly to the browser.")
    add_text(document, f"The project controls relevant to this topic are {controls}. These controls are significant because the platform works with security alerts, potential ransomware activity, media evidence and incident records. The system therefore retains context such as organization, request identifier, user/actor where available, time, source endpoint, file/evidence identity and workflow status. A displayed dashboard item is intended to be traceable to its originating event, analysis request, evidence item or operational state instead of being an isolated, unexplained warning.")
    add_text(document, f"The expected project output is {output}. Outputs are deliberately evidence-oriented. A security decision can include a factor list, score explanation, policy escalation reason, link to supporting events, original-file hash, manifest verification outcome, model/runtime result or response lifecycle state. This lets a user review what the system observed and why it produced the status. It does not convert a score or model result into absolute proof without analyst review and the supporting evidence.")
    add_text(document, formula)
    if diagram:
        add_figure(document, DIAGRAMS / diagram, caption)
    add_text(document, "Boundary of this report: only source-confirmed DDH capabilities are described. External command-sandbox, recovery-runner, threat-intelligence provider, object-lock storage or delivery services require their own deployment/configuration before they become operational. Likewise, a media model result is category-dependent and a basic file watcher cannot guarantee every read-only access event without the required audit source. These boundaries are retained so the project report does not claim features that are not present in the implementation.")


