    subtitle.alignment = WD_ALIGN_PARAGRAPH.CENTER
    subtitle.runs[0].bold = True
    add_text(document, "CHAPTER-WISE FULL PROJECT REPORT")
    document.paragraphs[-1].alignment = WD_ALIGN_PARAGRAPH.CENTER
    add_text(document, "Every chapter, topic and subtopic in this report begins with its own full project-specific page. Short summary pages have been removed. The report contains only details verified from the Digital Defense Hub repository and supplied reference format.")

